class Solution {
    public String oddString(String[] words) {
        int n = words[0].length();
        int[] diff0 = getDiff(words[0]);
        int[] diff1 = getDiff(words[1]);
        if (!java.util.Arrays.equals(diff0, diff1)) {
            int[] diff2 = getDiff(words[2]);
            return java.util.Arrays.equals(diff0, diff2) ? words[1] : words[0];
        }
        for (int i = 2; i < words.length; i++) {
            if (!java.util.Arrays.equals(diff0, getDiff(words[i]))) return words[i];
        }
        return "";
    }
    private int[] getDiff(String w) {
        int[] d = new int[w.length() - 1];
        for (int i = 0; i < d.length; i++) d[i] = w.charAt(i + 1) - w.charAt(i);
        return d;
    }
}
